    total_owners_equity = vars["Total Owner's Equity"]
    total_assets = vars["Total Assets"]
    total_liabilities = -total_owners_equity + total_assets

    return {
        "value": total_liabilities,
        "trace": {
            "Total Owner's Equity": total_owners_equity,
            "Total Assets": total_assets,
            "output_meta": {
                "currency": "$",
                "scale": "millions",
                "unit": None
            }
        }
    }
